def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 700:
                rich_opp += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 18.0 if hp > 3 else 45.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    supply_pressure = max(0.0, min(1.0, supply_pressure))

    my_urgent = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    base = 20.0 + 18.0 * supply_pressure

    if highest_prev >= 150:
        if critical:
            bid = 112.0 + 12.0 * supply_pressure
        elif my_urgent:
            bid = 86.0 + 10.0 * supply_pressure
        else:
            bid = 24.0 + 8.0 * supply_pressure
    elif highest_prev >= 100:
        if critical:
            bid = 96.0 + 10.0 * supply_pressure
        elif my_urgent:
            bid = 74.0 + 8.0 * supply_pressure
        else:
            bid = 28.0 + 8.0 * supply_pressure
    elif highest_prev >= 60:
        if critical:
            bid = highest_prev + 6.0
        elif my_urgent:
            bid = highest_prev + 2.5
        else:
            bid = max(base, avg_prev * 0.72)
    else:
        if critical:
            bid = 78.0
        elif my_urgent:
            bid = 58.0
        else:
            bid = base

    if rich_opp >= 2 and supply <= 18:
        bid += 8.0
    if urgent_opp >= 2 and not my_urgent:
        bid -= 4.0

    if day >= 8 and hp > 4 and no_water_days == 0:
        bid *= 0.9

    min_safe = 0.0
    if critical:
        min_safe = 72.0
    elif my_urgent:
        min_safe = 52.0

    bid = max(min_safe, bid)
    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids to infer aggressiveness
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    # Baseline aggressiveness from yesterday
    baseline = 0.0
    if prev_bids:
        baseline = max(prev_bids)

    # Supply pressure: higher supply means less need to overbid; lower supply means more urgency
    # Normalize supply to [0,1]
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    # Urgency based on our HP and consecutive no-water days
    # If low HP or already missing water, bid more.
    urgency = 0.0
    if hp <= 2.0:
        urgency = 1.0
    elif hp <= 4.0:
        urgency = 0.7
    elif hp <= 6.0:
        urgency = 0.45
    else:
        urgency = 0.25

    if no_water_days >= 2:
        urgency = max(urgency, 0.85)
    elif no_water_days == 1:
        urgency = max(urgency, 0.55)

    # Target bid: slightly below yesterday's max pressure when we can afford to save budget.
    # If our urgency is high, we pay closer to baseline.
    # Use a small undercut to beat typical overbidders.
    undercut = 3.0 + (1.0 - supply_norm) * 2.0  # more undercut when supply is higher

    # Desired fraction of baseline
    if baseline > 0.0:
        if urgency >= 0.85:
            target = baseline - 1.0
        elif urgency >= 0.55:
            target = baseline - undercut * 0.6
        else:
            target = baseline - undercut
    else:
        # Fallback: bid around a moderate level
        target = DAILY_SALARY * (0.45 + 0.35 * urgency - 0.15 * supply_norm)

    # Convert target into a cap tied to our budget and a safety reserve.
    # If budget is low, don't overspend.
    # Reserve more when hp is healthy.
    reserve_frac = 0.15 if hp <= 3.0 else 0.35
    max_affordable = max(0.0, budget * (1.0 - reserve_frac))

    # Also cap by a reasonable fraction of daily salary to avoid runaway bids.
    # When urgency is high, allow higher bids.
    salary_cap = DAILY_SALARY * (0.85 if urgency >= 0.85 else (0.65 if urgency >= 0.55 else 0.55))

    bid = min(target, max_affordable, salary_cap, budget)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    # If supply is very low, push up a bit to secure water
    if supply < (MIN_SUPPLY + 1.0):
        bid = max(bid, DAILY_SALARY * (0.55 + 0.25 * urgency))
        bid = min(bid, max_affordable, salary_cap, budget)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
